sketch.css:
.clock { display:flex; flex-direction:column; align-items:center; justify-content:center; width:100%; height:100%; box-sizing:border-box; background:transparent; font-family:"Segoe UI", system-ui, Roboto, Arial, sans-serif; color:var(--text); text-align:center; gap:4px; }
.time { font-size:40px; font-weight:600; font-variant-numeric:tabular-nums; letter-spacing:-0.02em; line-height:1.1; }
.date { font-size:13px; color:var(--muted); }

sketch.js:
function render(root, props, fire) {
  var DAYS = ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];
  var MONTHS = ["January","February","March","April","May","June","July","August","September","October","November","December"];
  function pad(n) { return (n < 10 ? "0" : "") + n; }
  function draw() {
    var d = new Date(), h = d.getHours(), t;
    if (props.Hour12) {
      var h12 = h % 12 || 12;
      t = h12 + ":" + pad(d.getMinutes()) + (props.ShowSeconds ? ":" + pad(d.getSeconds()) : "") + " " + (h < 12 ? "AM" : "PM");
    } else {
      t = pad(h) + ":" + pad(d.getMinutes()) + (props.ShowSeconds ? ":" + pad(d.getSeconds()) : "");
    }
    root.querySelector(".time").textContent = t;
    root.querySelector(".date").textContent = DAYS[d.getDay()] + ", " + d.getDate() + " " + MONTHS[d.getMonth()] + " " + d.getFullYear();
  }
  if (root.__clockTimer) clearInterval(root.__clockTimer);
  root.__clockTimer = setInterval(draw, 1000);
  draw();
}
